with base as (select * from inventory where (quantity != 190 and last_restock <= '2024-11-10') or product_id in (1, 2)), last_restock_month_summary as (select month(last_restock) as last_restock_month, sum(quantity) as total_quantity, round(avg(quantity), 2) as avg_quantity from base group by month(last_restock)) select last_restock_month, total_quantity, avg_quantity from last_restock_month_summary
